package rentivo_backend.config;
import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import rentivo_backend.entity.*; import rentivo_backend.repository.*; import java.util.*;
@Configuration public class DataSeeder { @Bean CommandLineRunner seed(CategoryRepository cats,UserRepository users,SubscriptionPlanRepository plans){return args->{for(String n:List.of("Property","Furniture","POP","Hardware")){cats.findByNameIgnoreCase(n).orElseGet(()->{Category c=new Category();c.setName(n);c.setActive(true);c.setSystemCategory(true);return cats.save(c);});} if(users.findByPhone("9999999999").isEmpty()){User u=new User();u.setName("Rentivo Owner");u.setPhone("9999999999");u.setPhoneVerified(true);u.setRole(User.Role.ADMIN);users.save(u);} };} }
